import { useState } from "react";

export function Tooltip({
  label = "{{label}}",
  text = "{{text}}",
  placement = "{{placement}}",
  accent = "{{accent}}",
  width = {{width}},
  visible: initialVisible = {{visible}},
}) {
  const [hovered, setHovered] = useState(false);
  const visible = hovered || initialVisible;
  const posStyle = {
    top: { bottom: "calc(50% + 34px)", left: "50%", transform: "translateX(-50%)" },
    bottom: { top: "calc(50% + 34px)", left: "50%", transform: "translateX(-50%)" },
    right: { left: "calc(50% + 70px)", top: "50%", transform: "translateY(-50%)" },
  }[placement] ?? {};
  const arrowStyle = {
    top: { bottom: -4, left: "50%", marginLeft: -4 },
    bottom: { top: -4, left: "50%", marginLeft: -4 },
    right: { left: -4, top: "50%", marginTop: -4 },
  }[placement] ?? {};
  return (
    <div style={{ position: "relative", minHeight: 200, display: "flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box" }}>
      <button type="button" aria-describedby="tooltip-1"
        onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)} onBlur={() => setHovered(false)}
        style={{ font: "500 14px system-ui, sans-serif", padding: "9px 16px", borderRadius: 8,
        border: "1.5px solid #24143033", background: "#FAF7F2", color: "#241430", cursor: "pointer" }}>
        {label}
      </button>
      <span role="tooltip" id="tooltip-1" style={{ position: "absolute", color: "#FAF7F2", fontSize: 13,
        lineHeight: 1.4, fontWeight: 500, padding: "7px 11px", borderRadius: 8, boxShadow: "0 10px 22px rgba(36,20,48,.24)",
        opacity: visible ? 1 : 0, visibility: visible ? "visible" : "hidden", transition: "opacity .15s ease",
        pointerEvents: "none", textAlign: "center", boxSizing: "border-box", maxWidth: width, background: accent, ...posStyle }}>
        {text}
        <span aria-hidden="true" style={{ position: "absolute", width: 8, height: 8, transform: "rotate(45deg)", background: accent, ...arrowStyle }} />
      </span>
    </div>
  );
}
